--
-- Table structure for table `biz_merchant_staff_role_archive`
--

DROP TABLE IF EXISTS `biz_merchant_staff_role_archive`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_merchant_staff_role_archive` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `enterprise_id` bigint DEFAULT NULL COMMENT '企业ID',
  `merchant_id` bigint DEFAULT NULL COMMENT '商户ID',
  `staff_id` bigint DEFAULT NULL COMMENT '商户人员ID',
  `role_code` varchar(32) NOT NULL COMMENT 'CONTACT CLERK PAYEE',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认，仅PAYEE有意义',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除',
  `contact_merchant_key` bigint GENERATED ALWAYS AS ((case when ((`role_code` = _utf8mb4'CONTACT') and (`deleted` = 0)) then `merchant_id` else NULL end)) STORED,
  `default_payee_merchant_key` bigint GENERATED ALWAYS AS ((case when ((`role_code` = _utf8mb4'PAYEE') and (`is_default` = 1) and (`deleted` = 0)) then `merchant_id` else NULL end)) STORED,
  `archive_batch_no` varchar(64) DEFAULT NULL COMMENT '归档批次号',
  `archived_at` datetime DEFAULT NULL COMMENT '归档时间',
  `archive_reason` varchar(500) DEFAULT NULL COMMENT '归档原因',
  PRIMARY KEY (`id`),
  KEY `idx_merchant_staff_role_list` (`enterprise_id`,`merchant_id`,`role_code`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=1067 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商户人员业务角色表';
/*!40101 SET character_set_client = @saved_cs_client */;

