  `type` tinyint DEFAULT '0' COMMENT '0旧车 1新车',
  `owner_type` tinyint DEFAULT '0' COMMENT '0个人 1组织',
  `owner_name` varchar(100) DEFAULT NULL COMMENT '车主姓名',
